INDEX_HTML = '<!DOCTYPE html>\n<html lang="es" data-theme="dark">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Observatorio LATAM — Plataforma de Desarrollo Socio-Económico y Ambiental</title>\n  <meta name="description" content="Observatorio de desarrollo económico, social y ambiental de América Latina y el Caribe. Datos comparables, metodologías auditadas (ADR-001) y snapshot versionado.">\n  <link rel="stylesheet" href="portal.css">\n  <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🌐</text></svg>">\n</head>\n<body>\n\n  <!-- =========================================================================\n       Header & Global Navigation\n       ========================================================================= -->\n  <header class="app-header" role="banner">\n    <div class="header-top">\n      <div class="brand-wrap">\n        <div class="brand-logo" aria-hidden="true">OL</div>\n        <div>\n          <h1 class="brand-title">\n            <span data-i18n="appName">Observatorio LATAM</span>\n            <span class="brand-badge">2026-09</span>\n          </h1>\n        </div>\n      </div>\n\n      <div class="header-actions">\n        <div class="meta-pill" id="header-snapshot-id">\n          <span class="status-dot"></span>\n          <span>Snapshot: 2026-09 · DOI: 10.5281/zenodo.obs-latam-2026-09</span>\n        </div>\n\n        <button class="theme-toggle" id="theme-toggle-btn" aria-label="Cambiar tema claro u oscuro">\n          ☀️ Claro\n        </button>\n\n        <div class="lang-selector" role="group" aria-label="Selector de idioma">\n          <button class="lang-btn active" data-lang="es" aria-label="Español">ES</button>\n          <button class="lang-btn" data-lang="pt" aria-label="Português">PT</button>\n          <button class="lang-btn" data-lang="en" aria-label="English">EN</button>\n        </div>\n      </div>\n    </div>\n\n    <nav class="nav-bar" role="navigation" aria-label="Navegación principal">\n      <div class="nav-container">\n        <a href="#portada" class="nav-link active" data-view="portada">\n          <span class="nav-icon" aria-hidden="true">🏠</span>\n          <span data-i18n="navPortada">Portada</span>\n        </a>\n        <a href="#comparador" class="nav-link" data-view="comparador">\n          <span class="nav-icon" aria-hidden="true">📊</span>\n          <span data-i18n="navComparador">Comparador</span>\n        </a>\n        <a href="#perfiles" class="nav-link" data-view="perfiles">\n          <span class="nav-icon" aria-hidden="true">🌎</span>\n          <span data-i18n="navPerfiles">Perfiles de País</span>\n        </a>\n        <a href="#visualizaciones" class="nav-link" data-view="visualizaciones">\n          <span class="nav-icon" aria-hidden="true">📈</span>\n          <span data-i18n="navVisualizaciones">8 Visualizaciones</span>\n        </a>\n        <a href="#historias" class="nav-link" data-view="historias">\n          <span class="nav-icon" aria-hidden="true">📖</span>\n          <span data-i18n="navHistorias">Historias</span>\n        </a>\n        <a href="#chat" class="nav-link" data-view="chat">\n          <span class="nav-icon" aria-hidden="true">💬</span>\n          <span data-i18n="navChat">Pregunta / Chat</span>\n        </a>\n        <a href="#metodologia" class="nav-link" data-view="metodologia">\n          <span class="nav-icon" aria-hidden="true">📑</span>\n          <span data-i18n="navMetodologia">Metodología & DOI</span>\n        </a>\n      </div>\n    </nav>\n  </header>\n\n  <!-- =========================================================================\n       Main Content (7 SPA Views)\n       ========================================================================= -->\n  <main class="main-content" role="main">\n\n    <!-- View 1: Portada (Overview & Pulse Cards) -->\n    <section id="view-portada" class="view-section active" aria-labelledby="view-portada-title">\n      <!-- Injected via portal.js renderPortada() -->\n      <div class="loading-state">Cargando indicadores prioritarios...</div>\n    </section>\n\n    <!-- View 2: Comparador (Interactive Explorer) -->\n    <section id="view-comparador" class="view-section" aria-labelledby="view-comparador-title">\n      <!-- Injected via portal.js renderComparador() -->\n      <div class="loading-state">Inicializando comparador interactivo...</div>\n    </section>\n\n    <!-- View 3: Perfiles de País (Country Dimensions) -->\n    <section id="view-perfiles" class="view-section" aria-labelledby="view-perfiles-title">\n      <!-- Injected via portal.js renderPerfiles() -->\n      <div class="loading-state">Cargando perfiles nacionales...</div>\n    </section>\n\n    <!-- View 4: 8 Visualizaciones Especializadas -->\n    <section id="view-visualizaciones" class="view-section" aria-labelledby="view-visualizaciones-title">\n      <!-- Injected via portal.js renderVisualizaciones() -->\n      <div class="loading-state">Cargando visualizaciones avanzadas...</div>\n    </section>\n\n    <!-- View 5: Historias Scrollytelling (Martini Glass) -->\n    <section id="view-historias" class="view-section" aria-labelledby="view-historias-title">\n      <!-- Injected via portal.js renderHistorias() -->\n      <div class="loading-state">Cargando historias interactivas...</div>\n    </section>\n\n    <!-- View 6: Pregunta / Chat UI (Agentic Chatbot) -->\n    <section id="view-chat" class="view-section" aria-labelledby="view-chat-title">\n      <!-- Injected via portal.js renderChat() -->\n      <div class="loading-state">Conectando al agente analítico...</div>\n    </section>\n\n    <!-- View 7: Metodología / DOI (Zenodo & ADR-001) -->\n    <section id="view-metodologia" class="view-section" aria-labelledby="view-metodologia-title">\n      <!-- Injected via portal.js renderMetodologia() -->\n      <div class="loading-state">Cargando documentación metodológica...</div>\n    </section>\n\n  </main>\n\n  <!-- =========================================================================\n       Footer\n       ========================================================================= -->\n  <footer class="app-footer" role="contentinfo">\n    <div class="footer-container">\n      <div>\n        <strong>Observatorio LATAM</strong> · Snapshot mensual <code>2026-09</code>\n        <div style="font-size:0.75rem; margin-top:0.25rem;">\n          5 países prioritarios (COL, CHL, CRI, BRA, MEX) · 15 países regionales · 15 indicadores auditados\n        </div>\n      </div>\n      <div>\n        <a href="https://doi.org/10.5281/zenodo.obs-latam-2026-09" target="_blank" rel="noopener noreferrer" class="meta-pill" style="text-decoration:none;">\n          DOI: 10.5281/zenodo.obs-latam-2026-09\n        </a>\n      </div>\n    </div>\n  </footer>\n\n  <!-- App Script -->\n  <script src="portal.js"></script>\n</body>\n</html>\n'
PORTAL_CSS = '/* ==========================================================================\n   Observatorio LATAM — Web Portal Stylesheet (ADR-002)\n   Fixed Okabe-Ito Colorblind-Safe Palette · Responsive · Accessible\n   ========================================================================== */\n\n:root {\n  /* Okabe-Ito Colorblind-Safe Palette for Priority Countries */\n  --color-col: #0072B2; /* Azul */\n  --color-chl: #D55E00; /* Naranja rojizo */\n  --color-cri: #009E73; /* Verde azulado */\n  --color-bra: #E69F00; /* Amarillo ocre */\n  --color-mex: #CC79A7; /* Rosa púrpura */\n\n  /* Regional Aggregates */\n  --color-latam-avg: #94A3B8; /* Gris azulado medio */\n  --color-lcn: #64748B;\n  --color-oed: #6366F1;\n  --color-wld: #94A3B8;\n  --color-other-country: #64748B;\n\n  /* Typography */\n  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;\n  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;\n  --font-serif: "Charter", "Bitstream Charter", "Sitka Text", Cambria, Georgia, serif;\n\n  /* Transitions */\n  --transition-fast: 0.15s ease;\n  --transition-normal: 0.25s ease;\n}\n\n/* --------------------------------------------------------------------------\n   Themes: Dark (default) and Light\n   -------------------------------------------------------------------------- */\n[data-theme="dark"] {\n  --bg-app: #090d16;\n  --bg-surface: #0f172a;\n  --bg-surface-elevated: #1e293b;\n  --bg-surface-hover: #334155;\n  --bg-input: #1e293b;\n  --border-subtle: #1e293b;\n  --border-medium: #334155;\n  --border-strong: #475569;\n\n  --text-main: #f8fafc;\n  --text-muted: #94a3b8;\n  --text-dim: #64748b;\n  --text-inverse: #090d16;\n\n  --accent-cyan: #06b6d4;\n  --accent-emerald: #10b981;\n  --accent-amber: #f59e0b;\n  --accent-rose: #f43f5e;\n  --accent-purple: #8b5cf6;\n\n  --chart-grid: rgba(148, 163, 184, 0.12);\n  --chart-axis: #475569;\n  --chart-tooltip-bg: rgba(15, 23, 42, 0.95);\n  --chart-tooltip-border: #334155;\n\n  --badge-bg: #1e293b;\n  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);\n  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -2px rgba(0, 0, 0, 0.5);\n  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6), 0 4px 6px -4px rgba(0, 0, 0, 0.6);\n}\n\n[data-theme="light"] {\n  --bg-app: #f8fafc;\n  --bg-surface: #ffffff;\n  --bg-surface-elevated: #f1f5f9;\n  --bg-surface-hover: #e2e8f0;\n  --bg-input: #ffffff;\n  --border-subtle: #e2e8f0;\n  --border-medium: #cbd5e1;\n  --border-strong: #94a3b8;\n\n  --text-main: #0f172a;\n  --text-muted: #475569;\n  --text-dim: #64748b;\n  --text-inverse: #ffffff;\n\n  --accent-cyan: #0891b2;\n  --accent-emerald: #059669;\n  --accent-amber: #d97706;\n  --accent-rose: #e11d48;\n  --accent-purple: #7c3aed;\n\n  --chart-grid: rgba(100, 116, 139, 0.15);\n  --chart-axis: #94a3b8;\n  --chart-tooltip-bg: rgba(255, 255, 255, 0.95);\n  --chart-tooltip-border: #cbd5e1;\n\n  --badge-bg: #f1f5f9;\n  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1);\n  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);\n  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);\n}\n\n/* --------------------------------------------------------------------------\n   Base & Reset\n   -------------------------------------------------------------------------- */\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml {\n  font-size: 16px;\n  scroll-behavior: smooth;\n}\n\nbody {\n  font-family: var(--font-sans);\n  background-color: var(--bg-app);\n  color: var(--text-main);\n  line-height: 1.5;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Enforce tabular numerals across data displays */\n.tabular-nums,\ntable,\n.stat-val,\n.sparkline-val,\n.badge-num,\n.rank-badge,\n.delta-num {\n  font-variant-numeric: tabular-nums;\n  font-feature-settings: "tnum" 1;\n}\n\na {\n  color: var(--accent-cyan);\n  text-decoration: none;\n  transition: color var(--transition-fast);\n}\n\na:hover {\n  text-decoration: underline;\n}\n\nbutton {\n  font-family: inherit;\n  cursor: pointer;\n  border: none;\n  background: none;\n}\n\n/* Focus styles for accessibility (WCAG AA) */\n:focus-visible {\n  outline: 2px solid var(--accent-cyan);\n  outline-offset: 2px;\n}\n\n/* --------------------------------------------------------------------------\n   Layout Components\n   -------------------------------------------------------------------------- */\n.app-header {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  background-color: var(--bg-surface);\n  border-bottom: 1px solid var(--border-subtle);\n  backdrop-filter: blur(8px);\n}\n\n.header-top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.75rem 1.5rem;\n  max-width: 1400px;\n  margin: 0 auto;\n  gap: 1rem;\n}\n\n.brand-wrap {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n}\n\n.brand-logo {\n  width: 32px;\n  height: 32px;\n  border-radius: 8px;\n  background: linear-gradient(135deg, var(--color-cri) 0%, var(--color-col) 100%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: white;\n  font-weight: 800;\n  font-size: 1rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.brand-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n  letter-spacing: -0.01em;\n  color: var(--text-main);\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.brand-badge {\n  font-size: 0.7rem;\n  font-family: var(--font-mono);\n  background-color: rgba(6, 182, 212, 0.15);\n  color: var(--accent-cyan);\n  padding: 0.15rem 0.45rem;\n  border-radius: 9999px;\n  border: 1px solid rgba(6, 182, 212, 0.3);\n  font-weight: 600;\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n}\n\n.meta-pill {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  padding: 0.25rem 0.6rem;\n  border-radius: 6px;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  color: var(--text-muted);\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n}\n\n.status-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background-color: var(--accent-emerald);\n  box-shadow: 0 0 6px var(--accent-emerald);\n}\n\n.theme-toggle,\n.lang-btn {\n  padding: 0.4rem 0.65rem;\n  border-radius: 6px;\n  font-size: 0.85rem;\n  font-weight: 500;\n  background: var(--bg-surface-elevated);\n  color: var(--text-muted);\n  border: 1px solid var(--border-subtle);\n  transition: all var(--transition-fast);\n}\n\n.theme-toggle:hover,\n.lang-btn:hover {\n  background: var(--bg-surface-hover);\n  color: var(--text-main);\n}\n\n.lang-selector {\n  display: flex;\n  background: var(--bg-surface-elevated);\n  border-radius: 6px;\n  border: 1px solid var(--border-subtle);\n  overflow: hidden;\n}\n\n.lang-btn {\n  border: none;\n  border-radius: 0;\n  padding: 0.35rem 0.6rem;\n  font-size: 0.75rem;\n  font-weight: 600;\n}\n\n.lang-btn.active {\n  background: var(--accent-cyan);\n  color: #ffffff;\n}\n\n/* --------------------------------------------------------------------------\n   Primary Navigation Bar\n   -------------------------------------------------------------------------- */\n.nav-bar {\n  border-top: 1px solid var(--border-subtle);\n  background: var(--bg-surface);\n  overflow-x: auto;\n  white-space: nowrap;\n}\n\n.nav-container {\n  display: flex;\n  max-width: 1400px;\n  margin: 0 auto;\n  padding: 0 1rem;\n  gap: 0.25rem;\n}\n\n.nav-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.75rem 1rem;\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  border-bottom: 2px solid transparent;\n  text-decoration: none;\n  transition: all var(--transition-fast);\n}\n\n.nav-link:hover {\n  color: var(--text-main);\n  text-decoration: none;\n  background-color: var(--bg-surface-hover);\n}\n\n.nav-link.active {\n  color: var(--accent-cyan);\n  border-bottom-color: var(--accent-cyan);\n}\n\n.nav-icon {\n  font-size: 1rem;\n}\n\n/* --------------------------------------------------------------------------\n   Main Content Layout\n   -------------------------------------------------------------------------- */\n.main-content {\n  flex: 1;\n  max-width: 1400px;\n  width: 100%;\n  margin: 0 auto;\n  padding: 2rem 1.5rem 4rem;\n}\n\n.view-section {\n  display: none;\n  animation: fadeIn 0.2s ease-in-out;\n}\n\n.view-section.active {\n  display: block;\n}\n\n@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(4px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n/* Page Section Headers */\n.view-header {\n  margin-bottom: 2rem;\n  border-bottom: 1px solid var(--border-subtle);\n  padding-bottom: 1.25rem;\n}\n\n.view-kicker {\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--accent-cyan);\n  margin-bottom: 0.4rem;\n  font-weight: 600;\n}\n\n.view-title {\n  font-size: 1.85rem;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  color: var(--text-main);\n}\n\n.view-desc {\n  margin-top: 0.5rem;\n  color: var(--text-muted);\n  font-size: 0.95rem;\n  max-width: 900px;\n}\n\n/* --------------------------------------------------------------------------\n   View 1: Portada (Pulse Cards + Insights Findings)\n   -------------------------------------------------------------------------- */\n.portada-hero {\n  background: linear-gradient(135deg, rgba(6, 182, 212, 0.08) 0%, rgba(16, 185, 129, 0.05) 100%);\n  border: 1px solid var(--border-medium);\n  border-radius: 12px;\n  padding: 1.75rem;\n  margin-bottom: 2.5rem;\n}\n\n.portada-hero-title {\n  font-size: 1.5rem;\n  font-weight: 700;\n  margin-bottom: 0.5rem;\n}\n\n.portada-hero-lead {\n  color: var(--text-muted);\n  font-size: 0.95rem;\n  max-width: 1000px;\n  line-height: 1.6;\n}\n\n.section-subtitle {\n  font-size: 1.25rem;\n  font-weight: 700;\n  margin: 2rem 0 1rem;\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n}\n\n.pulse-dimension-title {\n  font-size: 1.05rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  margin: 1.5rem 0 0.75rem;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding-bottom: 0.35rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.pulse-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\n  gap: 1rem;\n  margin-bottom: 1.5rem;\n}\n\n.pulse-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 10px;\n  padding: 1.2rem;\n  position: relative;\n  overflow: hidden;\n  transition: transform var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);\n  box-shadow: var(--shadow-sm);\n}\n\n.pulse-card:hover {\n  transform: translateY(-2px);\n  border-color: var(--border-strong);\n  box-shadow: var(--shadow-md);\n}\n\n.pulse-card-bar {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 4px;\n}\n\n.pulse-card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  margin-bottom: 0.6rem;\n}\n\n.country-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-weight: 700;\n  font-size: 0.85rem;\n  padding: 0.2rem 0.55rem;\n  border-radius: 6px;\n  color: #ffffff;\n}\n\n.rank-pill {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  padding: 0.15rem 0.45rem;\n  border-radius: 4px;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  color: var(--text-muted);\n  font-weight: 600;\n}\n\n.pulse-stat-val {\n  font-size: 1.8rem;\n  font-weight: 800;\n  line-height: 1.1;\n  color: var(--text-main);\n  margin-bottom: 0.2rem;\n}\n\n.pulse-stat-unit {\n  font-size: 0.8rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.pulse-year-badge {\n  font-size: 0.7rem;\n  font-family: var(--font-mono);\n  background: var(--badge-bg);\n  border: 1px solid var(--border-subtle);\n  padding: 0.1rem 0.35rem;\n  border-radius: 4px;\n  color: var(--text-dim);\n  margin-left: 0.4rem;\n}\n\n.pulse-sparkline {\n  margin: 0.75rem 0;\n  height: 38px;\n  width: 100%;\n}\n\n.pulse-sparkline svg {\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n\n.pulse-gaps {\n  font-size: 0.78rem;\n  border-top: 1px solid var(--border-subtle);\n  padding-top: 0.6rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.25rem;\n  color: var(--text-muted);\n}\n\n.pulse-gap-row {\n  display: flex;\n  justify-content: space-between;\n}\n\n.pulse-gap-val {\n  font-weight: 600;\n}\n\n.pulse-gap-val.positive {\n  color: var(--accent-emerald);\n}\n\n.pulse-gap-val.negative {\n  color: var(--accent-rose);\n}\n\n/* Insights Findings Cards */\n.insights-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));\n  gap: 1.25rem;\n  margin-top: 1rem;\n}\n\n.insight-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 10px;\n  padding: 1.4rem;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  box-shadow: var(--shadow-sm);\n  transition: border-color var(--transition-fast);\n}\n\n.insight-card:hover {\n  border-color: var(--border-strong);\n}\n\n.insight-badge {\n  display: inline-block;\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  font-weight: 600;\n  padding: 0.2rem 0.55rem;\n  border-radius: 4px;\n  background: rgba(6, 182, 212, 0.1);\n  color: var(--accent-cyan);\n  border: 1px solid rgba(6, 182, 212, 0.25);\n  margin-bottom: 0.6rem;\n}\n\n.insight-headline {\n  font-size: 1.05rem;\n  font-weight: 700;\n  line-height: 1.35;\n  color: var(--text-main);\n  margin-bottom: 0.6rem;\n}\n\n.insight-summary {\n  font-size: 0.88rem;\n  color: var(--text-muted);\n  line-height: 1.5;\n  margin-bottom: 1rem;\n  flex-grow: 1;\n}\n\n.insight-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  border-top: 1px solid var(--border-subtle);\n  padding-top: 0.75rem;\n  font-size: 0.78rem;\n  color: var(--text-dim);\n}\n\n.insight-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: var(--accent-cyan);\n}\n\n/* --------------------------------------------------------------------------\n   View 2: Comparador (Interactive Explorer)\n   -------------------------------------------------------------------------- */\n.comparator-panel {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.5rem;\n  margin-bottom: 1.5rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.comparator-controls {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n  gap: 1.25rem;\n  margin-bottom: 1.25rem;\n}\n\n.control-group {\n  display: flex;\n  flex-direction: column;\n  gap: 0.4rem;\n}\n\n.control-label {\n  font-size: 0.82rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--text-muted);\n}\n\n.select-input,\n.text-input {\n  background: var(--bg-input);\n  border: 1px solid var(--border-medium);\n  color: var(--text-main);\n  padding: 0.6rem 0.85rem;\n  border-radius: 8px;\n  font-size: 0.9rem;\n  font-family: inherit;\n  width: 100%;\n  transition: border-color var(--transition-fast);\n}\n\n.select-input:focus,\n.text-input:focus {\n  border-color: var(--accent-cyan);\n}\n\n.country-chip-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin-top: 0.4rem;\n}\n\n.country-chip {\n  padding: 0.25rem 0.6rem;\n  border-radius: 6px;\n  font-size: 0.78rem;\n  font-weight: 600;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-subtle);\n  color: var(--text-muted);\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  transition: all var(--transition-fast);\n}\n\n.country-chip:hover {\n  background: var(--bg-surface-hover);\n  color: var(--text-main);\n}\n\n.country-chip.active {\n  color: #ffffff;\n  border-color: transparent;\n}\n\n.chip-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  display: inline-block;\n}\n\n.ref-checkboxes {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n  align-items: center;\n  margin-top: 0.4rem;\n}\n\n.ref-label {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.82rem;\n  color: var(--text-muted);\n  cursor: pointer;\n}\n\n.view-switcher-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  border-top: 1px solid var(--border-subtle);\n  padding-top: 1rem;\n  margin-top: 1rem;\n  flex-wrap: wrap;\n  gap: 0.75rem;\n}\n\n.view-tabs {\n  display: flex;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-subtle);\n  border-radius: 8px;\n  padding: 0.2rem;\n  gap: 0.2rem;\n}\n\n.view-tab-btn {\n  padding: 0.45rem 0.9rem;\n  border-radius: 6px;\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  transition: all var(--transition-fast);\n}\n\n.view-tab-btn.active {\n  background: var(--accent-cyan);\n  color: #ffffff;\n}\n\n.export-actions {\n  display: flex;\n  gap: 0.5rem;\n}\n\n.btn-secondary {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  padding: 0.45rem 0.85rem;\n  font-size: 0.82rem;\n  font-weight: 600;\n  border-radius: 6px;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  color: var(--text-muted);\n  transition: all var(--transition-fast);\n}\n\n.btn-secondary:hover {\n  background: var(--bg-surface-hover);\n  color: var(--text-main);\n  border-color: var(--border-strong);\n}\n\n/* Chart Canvas Container */\n.chart-container {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.5rem;\n  position: relative;\n  min-height: 480px;\n  display: flex;\n  flex-direction: column;\n}\n\n.chart-header {\n  margin-bottom: 1.25rem;\n}\n\n.conclusion-title {\n  font-size: 1.25rem;\n  font-weight: 700;\n  color: var(--text-main);\n  line-height: 1.35;\n}\n\n.chart-subtitle {\n  font-size: 0.85rem;\n  color: var(--text-muted);\n  margin-top: 0.25rem;\n}\n\n.chart-svg-wrap {\n  flex: 1;\n  width: 100%;\n  min-height: 400px;\n  position: relative;\n}\n\n.chart-svg-wrap svg {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n/* Tooltip */\n.chart-tooltip {\n  position: absolute;\n  pointer-events: none;\n  background: var(--chart-tooltip-bg);\n  border: 1px solid var(--chart-tooltip-border);\n  padding: 0.6rem 0.85rem;\n  border-radius: 8px;\n  font-size: 0.82rem;\n  box-shadow: var(--shadow-lg);\n  z-index: 100;\n  opacity: 0;\n  transition: opacity 0.1s ease;\n  min-width: 140px;\n}\n\n.chart-tooltip-title {\n  font-weight: 700;\n  margin-bottom: 0.35rem;\n  color: var(--text-main);\n  border-bottom: 1px solid var(--border-subtle);\n  padding-bottom: 0.25rem;\n}\n\n.chart-tooltip-row {\n  display: flex;\n  justify-content: space-between;\n  gap: 1rem;\n  margin: 0.2rem 0;\n}\n\n/* Accessible Data Table */\n.table-wrap {\n  width: 100%;\n  overflow-x: auto;\n  margin-top: 1rem;\n}\n\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.88rem;\n  text-align: left;\n}\n\n.data-table th,\n.data-table td {\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.data-table th {\n  background: var(--bg-surface-elevated);\n  font-weight: 700;\n  color: var(--text-muted);\n  text-transform: uppercase;\n  font-size: 0.75rem;\n  letter-spacing: 0.05em;\n}\n\n.data-table tbody tr:hover {\n  background: var(--bg-surface-hover);\n}\n\n/* --------------------------------------------------------------------------\n   View 3: Perfiles de País (Country Profiles)\n   -------------------------------------------------------------------------- */\n.profile-selector-bar {\n  display: flex;\n  gap: 0.75rem;\n  align-items: center;\n  margin-bottom: 2rem;\n  flex-wrap: wrap;\n}\n\n.profile-hero {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 2rem;\n  margin-bottom: 2rem;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 1.5rem;\n  border-left: 6px solid var(--accent-cyan);\n}\n\n.profile-hero-meta {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n}\n\n.profile-country-name {\n  font-size: 2.2rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n}\n\n.profile-tags {\n  display: flex;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n\n.profile-tag {\n  font-size: 0.78rem;\n  padding: 0.2rem 0.55rem;\n  border-radius: 4px;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  color: var(--text-muted);\n}\n\n/* Methodological Warning Banner for SI.POV.NAHC */\n.disclaimer-banner {\n  background: rgba(245, 158, 11, 0.1);\n  border: 1px solid rgba(245, 158, 11, 0.3);\n  border-left: 4px solid var(--accent-amber);\n  border-radius: 8px;\n  padding: 1.1rem 1.4rem;\n  margin: 1.75rem 0;\n  color: var(--text-main);\n  font-size: 0.88rem;\n  line-height: 1.5;\n}\n\n.disclaimer-banner-title {\n  font-weight: 700;\n  color: var(--accent-amber);\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  margin-bottom: 0.35rem;\n  text-transform: uppercase;\n  font-size: 0.8rem;\n  letter-spacing: 0.05em;\n}\n\n/* Dimensions Grid for Profiles */\n.profile-dimensions-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n  gap: 1.5rem;\n  margin-top: 1.5rem;\n}\n\n.dimension-box {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.5rem;\n}\n\n.dimension-box-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n  margin-bottom: 1.25rem;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding-bottom: 0.5rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.profile-indicator-card {\n  border-bottom: 1px solid var(--border-subtle);\n  padding: 0.85rem 0;\n}\n\n.profile-indicator-card:last-child {\n  border-bottom: none;\n}\n\n.profile-ind-header {\n  display: flex;\n  justify-content: space-between;\n  margin-bottom: 0.25rem;\n}\n\n.profile-ind-name {\n  font-size: 0.85rem;\n  font-weight: 600;\n  color: var(--text-muted);\n}\n\n.profile-ind-val {\n  font-size: 1.15rem;\n  font-weight: 800;\n  color: var(--text-main);\n}\n\n/* --------------------------------------------------------------------------\n   View 4: 8 Visualizaciones Especializadas\n   -------------------------------------------------------------------------- */\n.vis-subnav {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  background: var(--bg-surface);\n  padding: 0.6rem;\n  border-radius: 10px;\n  border: 1px solid var(--border-subtle);\n  margin-bottom: 1.75rem;\n}\n\n.vis-btn {\n  padding: 0.5rem 0.9rem;\n  border-radius: 6px;\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  background: transparent;\n  transition: all var(--transition-fast);\n}\n\n.vis-btn:hover {\n  background: var(--bg-surface-hover);\n  color: var(--text-main);\n}\n\n.vis-btn.active {\n  background: var(--accent-cyan);\n  color: #ffffff;\n}\n\n.vis-container {\n  display: none;\n}\n\n.vis-container.active {\n  display: block;\n}\n\n/* Interactive Composite Index Builder */\n.builder-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1.5rem;\n  margin-top: 1rem;\n}\n\n@media (max-width: 900px) {\n  .builder-grid {\n    grid-template-columns: 1fr;\n  }\n}\n\n.builder-controls {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.5rem;\n}\n\n.builder-slider-row {\n  margin-bottom: 1rem;\n  padding-bottom: 0.75rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.builder-slider-header {\n  display: flex;\n  justify-content: space-between;\n  font-size: 0.82rem;\n  font-weight: 600;\n  margin-bottom: 0.35rem;\n}\n\n.builder-slider {\n  width: 100%;\n  accent-color: var(--accent-cyan);\n  cursor: pointer;\n}\n\n.builder-summary-pill {\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  padding: 0.35rem 0.75rem;\n  border-radius: 6px;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  display: flex;\n  justify-content: space-between;\n  margin-bottom: 1rem;\n}\n\n/* Coverage Heatmap */\n.heatmap-wrap {\n  overflow-x: auto;\n  margin-top: 1rem;\n}\n\n.heatmap-table {\n  border-collapse: separate;\n  border-spacing: 2px;\n  font-size: 0.78rem;\n  width: 100%;\n}\n\n.heatmap-cell {\n  width: 38px;\n  height: 32px;\n  text-align: center;\n  border-radius: 4px;\n  font-family: var(--font-mono);\n  font-weight: 700;\n  font-size: 0.7rem;\n  color: #ffffff;\n  cursor: pointer;\n  transition: transform 0.1s ease;\n}\n\n.heatmap-cell:hover {\n  transform: scale(1.15);\n  z-index: 10;\n}\n\n/* --------------------------------------------------------------------------\n   View 5: Scrollytelling ("Copa de Martini")\n   -------------------------------------------------------------------------- */\n.scrolly-story-tabs {\n  display: flex;\n  gap: 0.5rem;\n  margin-bottom: 1.5rem;\n}\n\n.story-btn {\n  padding: 0.6rem 1.2rem;\n  font-size: 0.9rem;\n  font-weight: 600;\n  border-radius: 8px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  color: var(--text-muted);\n}\n\n.story-btn.active {\n  background: var(--accent-cyan);\n  color: #ffffff;\n  border-color: transparent;\n}\n\n.scrolly-layout {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 2rem;\n  align-items: start;\n}\n\n@media (max-width: 900px) {\n  .scrolly-layout {\n    grid-template-columns: 1fr;\n  }\n}\n\n.scrolly-steps {\n  display: flex;\n  flex-direction: column;\n  gap: 1.5rem;\n}\n\n.scrolly-step {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.5rem;\n  cursor: pointer;\n  transition: all var(--transition-fast);\n  border-left: 4px solid transparent;\n}\n\n.scrolly-step:hover {\n  border-color: var(--border-strong);\n}\n\n.scrolly-step.active {\n  border-left-color: var(--accent-cyan);\n  background: var(--bg-surface-elevated);\n  box-shadow: var(--shadow-md);\n}\n\n.step-num-pill {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  font-weight: 700;\n  color: var(--accent-cyan);\n  text-transform: uppercase;\n  margin-bottom: 0.4rem;\n}\n\n.step-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n  margin-bottom: 0.6rem;\n  color: var(--text-main);\n}\n\n.step-body {\n  font-size: 0.92rem;\n  color: var(--text-muted);\n  line-height: 1.6;\n}\n\n.scrolly-chart-sticky {\n  position: sticky;\n  top: 6rem;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.5rem;\n  min-height: 480px;\n  box-shadow: var(--shadow-sm);\n}\n\n.explore-action-box {\n  margin-top: 1.5rem;\n  padding: 1.25rem;\n  border-radius: 10px;\n  background: linear-gradient(135deg, rgba(6, 182, 212, 0.1) 0%, rgba(16, 185, 129, 0.08) 100%);\n  border: 1px solid rgba(6, 182, 212, 0.3);\n  text-align: center;\n}\n\n.btn-primary {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.7rem 1.4rem;\n  font-size: 0.95rem;\n  font-weight: 700;\n  border-radius: 8px;\n  background: var(--accent-cyan);\n  color: #ffffff;\n  box-shadow: var(--shadow-sm);\n  transition: all var(--transition-fast);\n}\n\n.btn-primary:hover {\n  background: #0891b2;\n  transform: translateY(-1px);\n  box-shadow: var(--shadow-md);\n  text-decoration: none;\n}\n\n/* --------------------------------------------------------------------------\n   View 6: Pregunta / Chat UI\n   -------------------------------------------------------------------------- */\n.chat-container {\n  display: flex;\n  flex-direction: column;\n  height: 720px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: var(--shadow-sm);\n}\n\n.chat-header {\n  padding: 1rem 1.5rem;\n  border-bottom: 1px solid var(--border-subtle);\n  background: var(--bg-surface-elevated);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.chat-messages {\n  flex: 1;\n  overflow-y: auto;\n  padding: 1.5rem;\n  display: flex;\n  flex-direction: column;\n  gap: 1.25rem;\n}\n\n.chat-bubble {\n  max-width: 80%;\n  padding: 1rem 1.25rem;\n  border-radius: 12px;\n  font-size: 0.92rem;\n  line-height: 1.55;\n}\n\n.chat-bubble.user {\n  align-self: flex-end;\n  background: var(--accent-cyan);\n  color: #ffffff;\n  border-bottom-right-radius: 2px;\n}\n\n.chat-bubble.assistant {\n  align-self: flex-start;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-subtle);\n  border-bottom-left-radius: 2px;\n  color: var(--text-main);\n  width: 100%;\n  max-width: 85%;\n}\n\n.verify-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  font-weight: 700;\n  padding: 0.2rem 0.55rem;\n  border-radius: 4px;\n  margin-bottom: 0.6rem;\n}\n\n.verify-badge.verified {\n  background: rgba(16, 185, 129, 0.15);\n  color: var(--accent-emerald);\n  border: 1px solid rgba(16, 185, 129, 0.3);\n}\n\n.verify-badge.out-of-catalog {\n  background: rgba(245, 158, 11, 0.15);\n  color: var(--accent-amber);\n  border: 1px solid rgba(245, 158, 11, 0.3);\n}\n\n.chat-inline-chart {\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 8px;\n  padding: 1rem;\n  margin: 0.85rem 0;\n  min-height: 220px;\n}\n\n.chat-source-card {\n  font-size: 0.75rem;\n  font-family: var(--font-mono);\n  background: var(--bg-app);\n  border: 1px solid var(--border-subtle);\n  border-radius: 6px;\n  padding: 0.5rem 0.75rem;\n  color: var(--text-muted);\n  margin-top: 0.6rem;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.chat-suggestions {\n  padding: 0.75rem 1.5rem;\n  background: var(--bg-surface);\n  border-top: 1px solid var(--border-subtle);\n  display: flex;\n  gap: 0.5rem;\n  overflow-x: auto;\n  white-space: nowrap;\n}\n\n.suggestion-chip {\n  padding: 0.35rem 0.75rem;\n  border-radius: 9999px;\n  font-size: 0.78rem;\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  color: var(--text-muted);\n  cursor: pointer;\n  transition: all var(--transition-fast);\n}\n\n.suggestion-chip:hover {\n  background: var(--bg-surface-hover);\n  color: var(--text-main);\n  border-color: var(--accent-cyan);\n}\n\n.chat-input-bar {\n  padding: 1rem 1.5rem;\n  border-top: 1px solid var(--border-subtle);\n  background: var(--bg-surface-elevated);\n  display: flex;\n  gap: 0.75rem;\n}\n\n.chat-input {\n  flex: 1;\n  background: var(--bg-input);\n  border: 1px solid var(--border-medium);\n  border-radius: 8px;\n  padding: 0.7rem 1rem;\n  color: var(--text-main);\n  font-family: inherit;\n  font-size: 0.95rem;\n}\n\n/* --------------------------------------------------------------------------\n   View 7: Metodología / DOI\n   -------------------------------------------------------------------------- */\n.methodology-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 1.5rem;\n}\n\n.methodology-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 1.75rem;\n  box-shadow: var(--shadow-sm);\n}\n\n.citation-box {\n  background: var(--bg-surface-elevated);\n  border: 1px solid var(--border-medium);\n  border-radius: 8px;\n  padding: 1.25rem;\n  font-family: var(--font-mono);\n  font-size: 0.85rem;\n  line-height: 1.5;\n  color: var(--text-main);\n  position: relative;\n  margin: 1rem 0;\n}\n\n.adr-item {\n  border-left: 3px solid var(--accent-cyan);\n  padding-left: 1.25rem;\n  margin: 1.25rem 0;\n}\n\n.adr-code {\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  background: var(--bg-surface-elevated);\n  padding: 0.2rem 0.5rem;\n  border-radius: 4px;\n  color: var(--accent-cyan);\n}\n\n.download-links-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 0.75rem;\n  margin-top: 1rem;\n}\n\n/* --------------------------------------------------------------------------\n   Footer\n   -------------------------------------------------------------------------- */\n.app-footer {\n  border-top: 1px solid var(--border-subtle);\n  background: var(--bg-surface);\n  padding: 2rem 1.5rem;\n  font-size: 0.85rem;\n  color: var(--text-muted);\n}\n\n.footer-container {\n  max-width: 1400px;\n  margin: 0 auto;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 1rem;\n}\n\n/* --------------------------------------------------------------------------\n   Responsive Breakpoints\n   -------------------------------------------------------------------------- */\n@media (max-width: 768px) {\n  .header-top {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n  .header-actions {\n    width: 100%;\n    justify-content: space-between;\n  }\n  .pulse-grid,\n  .insights-grid {\n    grid-template-columns: 1fr;\n  }\n  .chart-container {\n    min-height: 380px;\n    padding: 1rem;\n  }\n  .chat-bubble.assistant,\n  .chat-bubble.user {\n    max-width: 95%;\n  }\n}\n'
